43	// Reads a local ruleset file from disk and parses it.
44	async function readRuleset(absolute: string): Promise<Ruleset> {
45	  const raw = await fs.promises.readFile(absolute, { encoding: 'utf8' });
46	  const parsed = YAML.parse(raw);
47	  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
48	    throw new Error(`Ruleset at ${absolute} must be an object at the top level.`);
49	  }
50	  return parsed as Ruleset;
51	}
