151	    }
152	    if (ALLOWED_EXTENDS_IDENTIFIERS.includes(entry)) continue;
153	    await validateRemoteExtends(parseRemoteExtendsUrl(entry, url), nextVisited, depth + 1);
154	  }
155	}
