// ** For main process only. Do not import this file into the renderer **
// Caches compiled Spectral rulesets on disk, one per project, at
// <dataPath>/projects/<projectId>/.spectral.yaml. Compiling a ruleset (fetching and inlining its
// remote "extends") is expensive and hits the network, so we skip recompilation when the source
// content is unchanged and the compiled file is still present on disk.

// projectId -> hash of the source content last compiled for that project.
const contentHashCache = new Map<string, string>();

function getDataPath(): string {
  return process.env.INSOMNIA_DATA_PATH || electron.app.getPath('userData');
}

function hashContent(content: string): string {
  return createHash('sha256').update(content).digest('hex');
}

// Absolute path where the compiled ruleset for a given project is stored.
export function compiledRulesetPathFor(projectId: string): string {
  return path.join(getDataPath(), 'projects', projectId, '.spectral.yaml');
}

// Compiles the given ruleset content and writes it to the project's compiled path, creating the
// containing directory first. Uses a content-hash cache to skip recompilation and the write when
// the content is unchanged and the compiled file still exists on disk. Errors thrown by
// compileSpectralRulesetFromContent propagate to the caller (and leave the cache untouched).
export async function writeCompiledRuleset(projectId: string, content: string): Promise<{ compiledPath: string }> {
  const compiledPath = compiledRulesetPathFor(projectId);
  const hash = hashContent(content);

  if (contentHashCache.get(projectId) === hash) {
    try {
      await fs.promises.access(compiledPath);
      // Unchanged content and the compiled file is still on disk — nothing to do.
      return { compiledPath };
